function setStatus(message){dialogProgress.update(message);const status=$('#status-message');if(status){status.textContent=message;status.title=message;}}
function toast(message,error=false){document.querySelectorAll('.toast,.dialog-toast').forEach(node=>node.remove());const front=[...document.querySelectorAll('dialog[open]')].at(-1);const n=document.createElement('div');n.className=`${front?'dialog-toast':'toast'}${error?' error':''}`;n.setAttribute('role',error?'alert':'status');n.textContent=String(message);const panel=front?.querySelector('.dialog-progress');if(panel?.dataset.state==='complete'){panel.querySelector('[role="status"]').textContent=String(message);if(error)panel.dataset.state='error';setStatus(String(message));return;}if(panel?.dataset.state==='error'&&panel.querySelector('[role="status"]').textContent===String(message)){setStatus(String(message));return;}if(front)front.querySelector('.dialog-head').after(n);else document.body.append(n);setTimeout(()=>n.remove(),error?15000:5500);setStatus(String(message));}
